mapper.select:
SELECT COUNT(1) > 0
FROM evaluation
WHERE course_id = #{courseId}
  AND from_user_id = #{fromUserId}
  AND to_user_id = #{toUserId}
  AND deleted = 0

SELECT e.id, e.course_id, e.from_user_id, from_user.name as from_user_name, from_user.role as from_user_role, e.to_user_id, to_user.name as to_user_name, to_user.role as to_user_role, e.rating, e.content, e.create_time, c.start_time as course_start_time, c.end_time as course_end_time, c.table_number as course_table_number, c.status as course_status FROM evaluation e LEFT JOIN user from_user ON e.from_user_id = from_user.id LEFT JOIN user to_user ON e.to_user_id = to_user.id LEFT JOIN courses c ON e.course_id = c.id WHERE e.to_user_id = #{userId} AND e.deleted = 0
AND e.rating = #{queryDTO.rating}
ORDER BY e.create_time DESC LIMIT #{offset}, #{limit}

SELECT COUNT(1)
FROM evaluation e
WHERE e.to_user_id = #{userId}
AND e.deleted = 0

    AND e.rating = #{queryDTO.rating}
